head.script:
scwin.onpageload = function() {
    var totRow = 100;
    var totCol = grid1.getTotalCol();
    var arr = [];
    for (var i = 0; i < totRow; i++) {
        for (var j = 0; j < totCol; j++) {
            arr.push("index_" + i + "_" + j);
        }
    }
    grid1.setData(arr);
};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    /*
    for(var i=0;i<grid1.getTotalRow();i++) {
    	if(i != 50 && i != 100 && i != 199) {
    		grid1.setRowVisible(i, false);
    	}
    }
    */
    grid1.setRowBackgroundColor(50, "yellow");
    for (var i = 10; i < 50; i++) {
        grid1.setRowBackgroundColor(i, "yellow");
        grid1.setRowVisible(i, false);
    }
};
scwin.checkColor = function(id, value, rgb) {
    var color = WebSquare.wUnit.getJq(id).css("background-color");
    if (color.indexOf("rgb") != -1) {
        return color == rgb;
    }
    return color == value;
}

scwin.setVal1 = function() {
    WebSquare.wUnit.getJq('#grid1_scrollY_div').animate ({scrollTop:360}, 50);
}
scwin.setVal2 = function() {
    WebSquare.wUnit.getJq('#grid1_scrollY_div').animate ({scrollTop:50}, 50);
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getJq(WebSquare.wUnit.getJq('#grid1_body_tbody tr')[38]).css('display') == 'none' && WebSquare.wUnit.getJq(WebSquare.wUnit.getJq('#grid1_body_tbody tr')[38]).is(':visible') == false;
}

scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkColor('#grid1_cell_50_0', 'yellow', 'rgb(255, 255, 0)')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 세로스크롤을 아래로 조금씩 내리고 다시 위로 올려본다.
    //2. Lower the vertical scroll down and back up.
    //Verify step 2. Hidden rows are not shown.
    WebSquare.wUnit.addCommand("set", "scwin.setVal1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setVal2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
